"Friends of God from every age and land: their lives, feast days, patronages, and prayers, their own words, and help finding a patron for any need.": "Amigos de Dios de todos los tiempos y lugares: sus vidas, fiestas, patronazgos y oraciones, sus propias palabras y ayuda para encontrar un patrono para cada necesidad.",
