"How to pray the Rosary": "Cómo rezar el Rosario",
"On the crucifix, make the Sign of the Cross and pray the Apostles’ Creed.": "En el crucifijo, haz la señal de la cruz y reza el Credo de los Apóstoles.",
"On the first large bead, pray the Our Father.": "En la primera cuenta grande, reza el Padre nuestro.",
"On the next three beads, pray a Hail Mary each for faith, hope, and charity, then the Glory Be.": "En las tres cuentas siguientes, reza un Ave María en cada una por la fe, la esperanza y la caridad, y luego el Gloria.",
"Announce the first mystery, and pray the Our Father on the large bead.": "Anuncia el primer misterio y reza el Padre nuestro en la cuenta grande.",
"On the ten small beads, pray ten Hail Marys while meditating on the mystery.": "En las diez cuentas pequeñas, reza diez Avemarías mientras meditas el misterio.",
"End the decade with the Glory Be and the Fatima Prayer. Repeat for the other four mysteries.": "Termina la decena con el Gloria y la oración de Fátima. Repite con los otros cuatro misterios.",
"At the centerpiece, finish with the Hail, Holy Queen and the closing prayer.": "En la medalla central, termina con la Salve y la oración final.",
