"The Chaplet of Divine Mercy": "La Coronilla de la Divina Misericordia",
"Jesus, I trust in You": "Jesús, en ti confío",
"Jesus, I trust in You.": "Jesús, en ti confío.",
"Eternal Father": "Padre Eterno",
"For the Sake of His Sorrowful Passion": "Por su dolorosa Pasión",
"Holy God": "Santo Dios",
"Eternal Father, I offer You the Body and Blood, Soul and Divinity of Your dearly beloved Son, Our Lord Jesus Christ, in atonement for our sins and those of the whole world.": "Padre Eterno, te ofrezco el Cuerpo y la Sangre, el Alma y la Divinidad de tu amadísimo Hijo, nuestro Señor Jesucristo, como propiciación de nuestros pecados y los del mundo entero.",
"For the sake of His sorrowful Passion, have mercy on us and on the whole world.": "Por su dolorosa Pasión, ten misericordia de nosotros y del mundo entero.",
"Holy God, Holy Mighty One, Holy Immortal One, have mercy on us and on the whole world.": "Santo Dios, Santo Fuerte, Santo Inmortal, ten piedad de nosotros y del mundo entero.",
"You expired, Jesus, but the source of life gushed forth for souls, and an ocean of mercy opened up for the whole world. O Fount of Life, unfathomable Divine Mercy, envelop the whole world and empty Yourself out upon us.": "Expiraste, Jesús, pero la fuente de vida brotó para las almas y el mar de misericordia se abrió para el mundo entero. Oh Fuente de Vida, insondable Misericordia Divina, envuelve al mundo entero y derrámate sobre nosotros.",
"Eternal God, in whom mercy is endless and the treasury of compassion inexhaustible, look kindly upon us and increase Your mercy in us, that in difficult moments we might not despair nor become despondent, but with great confidence submit ourselves to Your holy will, which is Love and Mercy itself.": "Dios Eterno, en quien la misericordia es infinita y el tesoro de compasión inagotable, vuelve a nosotros tu mirada bondadosa y aumenta tu misericordia en nosotros, para que en momentos difíciles no nos desesperemos ni nos desanimemos, sino que, con gran confianza, nos sometamos a tu santa voluntad, que es el Amor y la Misericordia mismos.",
"How to pray the Chaplet": "Cómo rezar la Coronilla",
"Begin with the Sign of the Cross and the opening prayer.": "Empieza con la señal de la cruz y la oración inicial.",
"Pray one Our Father, one Hail Mary, and the Apostles’ Creed.": "Reza un Padre nuestro, un Ave María y el Credo de los Apóstoles.",
"On each large bead, pray “Eternal Father, I offer You…”": "En cada cuenta grande, reza «Padre Eterno, te ofrezco…»",
"On each of the ten small beads, pray “For the sake of His sorrowful Passion…”": "En cada una de las diez cuentas pequeñas, reza «Por su dolorosa Pasión…»",
"It is the Hour of Mercy now.": "Ahora es la Hora de la Misericordia.",
"You have prayed the Chaplet of Divine Mercy": "Has rezado la Coronilla de la Divina Misericordia",
"Pray the Chaplet again": "Rezar de nuevo la Coronilla",
"The Chaplet of the Sacred Heart": "La Coronilla del Sagrado Corazón",
"Chaplet of the Sacred Heart": "Coronilla del Sagrado Corazón",
"Sweet Heart of Jesus, be my love": "Dulce Corazón de Jesús, sé mi amor",
"Sweet Heart of Jesus, be my love.": "Dulce Corazón de Jesús, sé mi amor.",
"Sweet Heart of Mary": "Dulce Corazón de María",
"Sweet Heart of Mary, be my salvation.": "Dulce Corazón de María, sé la salvación mía.",
"O Sweetest Heart of Jesus": "Oh dulcísimo Corazón de Jesús",
"O Sweetest Heart of Jesus, I implore that I may ever love Thee more and more.": "Oh dulcísimo Corazón de Jesús, te suplico que te ame cada vez más.",
"May the Heart of Jesus in the Most Blessed Sacrament be praised, adored, and loved with grateful affection, at every moment, in all the tabernacles of the world, even to the end of time. Amen.": "Sea alabado, adorado y amado con grato afecto, en todo momento, el Corazón de Jesús en el Santísimo Sacramento, en todos los sagrarios del mundo, hasta el fin de los tiempos. Amén.",
"Soul of Christ": "Alma de Cristo",
"Soul of Christ, sanctify me.": "Alma de Cristo, santifícame.",
"Body of Christ, save me.": "Cuerpo de Cristo, sálvame.",
"Blood of Christ, inebriate me.": "Sangre de Cristo, embriágame.",
"Water from the side of Christ, wash me.": "Agua del costado de Cristo, lávame.",
"Passion of Christ, strengthen me.": "Pasión de Cristo, confórtame.",
"O good Jesus, hear me.": "Oh buen Jesús, óyeme.",
"Within thy wounds hide me.": "Dentro de tus llagas, escóndeme.",
"Suffer me not to be separated from thee.": "No permitas que me aparte de ti.",
"From the malicious enemy defend me.": "Del maligno enemigo, defiéndeme.",
"In the hour of my death call me": "En la hora de mi muerte, llámame",
"and bid me come unto thee,": "y mándame ir a ti,",
"that with thy saints I may praise thee": "para que con tus santos te alabe",
"forever and ever. Amen.": "por los siglos de los siglos. Amén.",
"The pendant": "La medalla",
"Thirty-three beads · about {n} minutes": "Treinta y tres cuentas · unos {n} minutos",
"On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).": "En el crucifijo, haz la señal de la cruz y reza el Alma de Cristo.",
"On each small bead, pray “Sweet Heart of Jesus, be my love.”": "En cada cuenta pequeña, reza «Dulce Corazón de Jesús, sé mi amor».",
"After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”": "Después de cada grupo de cuentas pequeñas, reza «Dulce Corazón de María, sé la salvación mía».",
