"Shelf": "Estante",
"List": "Lista",
"Read on Sanctify": "Leer en Sanctify",
"Choose a plan and read a little each day. Each reading links to the chapter on the USCCB website (New American Bible). Your progress is saved in this browser.": "Elige un plan y lee un poco cada día. Cada lectura enlaza con el capítulo en el sitio de la USCCB (New American Bible, en inglés). Tu progreso se guarda en este navegador.",
"The Four Gospels": "Los cuatro Evangelios",
"Walk with Jesus through Matthew, Mark, Luke, and John in a month.": "Camina con Jesús por Mateo, Marcos, Lucas y Juan en un mes.",
"Start this plan": "Empezar este plan",
"Psalms and Proverbs": "Salmos y Proverbios",
"Pray the Psalms and learn wisdom from Proverbs, about three chapters a day.": "Reza los Salmos y aprende sabiduría de los Proverbios, unos tres capítulos al día.",
"The New Testament": "El Nuevo Testamento",
"From Matthew to Revelation in three months.": "De Mateo al Apocalipsis en tres meses.",
"The Whole Bible in a Year": "Toda la Biblia en un año",
"All 73 books of the Catholic Bible, about four chapters a day.": "Los 73 libros de la Biblia católica, unos cuatro capítulos al día.",
"The core teachings of the Catholic faith, each with the Scripture passages and Catechism paragraphs behind it, the witness of the Church Fathers, and charitable answers to the objections Catholics most often hear.": "Las enseñanzas centrales de la fe católica, cada una con los pasajes de la Escritura y los números del Catecismo que la sustentan, el testimonio de los Padres de la Iglesia y respuestas caritativas a las objeciones que más oyen los católicos.",
"Show:": "Mostrar:",
