"to show them on a public profile and earn Community badges.": "para mostrarlas en un perfil público y ganar insignias de la Comunidad.",
"Prayer badges count the days you mark in your prayer tracker; finishing a Rosary, chaplet, or other guided prayer marks it for you.": "Las insignias de oración cuentan los días que marcas en tu registro de oración; al terminar un Rosario, una coronilla u otra oración guiada se marca solo.",
