"Erase your saved entries, novenas, intentions, prayer record, badges, and settings from this device? This can’t be undone. You may want to download a backup first.": "¿Borrar de este dispositivo tus entradas guardadas, novenas, intenciones, registro de oración, insignias y ajustes? No se puede deshacer. Quizá quieras descargar antes una copia de seguridad.",
"Replace what’s on this device with the backup from {*}?": "¿Reemplazar lo que hay en este dispositivo por la copia de seguridad del {*}?",
"follows the Roman Missal of 1962 and its calendar: the old feasts and seasons, Ember Days, the Latin Mass explained, and the fifteen mysteries of the Rosary. Its prayers are those of the Roman Catholic edition.": "sigue el Misal Romano de 1962 y su calendario: las antiguas fiestas y tiempos, las Témporas, la misa latina explicada y los quince misterios del Rosario. Sus oraciones son las de la edición católica romana.",
